SELECT u.id, u.institute_id, u.dept_id, u.referral_code, u.user_code, u.user_name, u.real_name, u.phone, u.email, u.avatar, u.`status`, u.status_time, u.status_memo, u.is_pwd_expired, u.pwd_level, u.pwd_edit_time, u.login_error_count, u.lasted_login_ip, u.lasted_login_time, u.third_id, u.create_time, inc.institute_name, dept.dept_name FROM bko_user AS u LEFT JOIN inc_institute AS inc ON u.institute_id = inc.id LEFT JOIN inc_department AS dept ON u.dept_id = dept.id WHERE u.delete_state = 0
AND ( u.user_name LIKE CONCAT('%', #{userName,jdbcType=VARCHAR}, '%') OR u.pin_yin LIKE CONCAT('%', UPPER(#{userName,jdbcType=VARCHAR}), '%') )
AND u.institute_id = #{instituteId,jdbcType=VARCHAR}
AND u.create_time BETWEEN #{createTimeStart,jdbcType=TIMESTAMP} AND #{createTimeEnd,jdbcType=TIMESTAMP}
AND ( u.institute_id = #{instituteParentId,jdbcType=VARCHAR} OR u.institute_id IN ( SELECT id FROM inc_institute WHERE delete_state = 0 AND parent_path Like CONCAT('%', #{instituteParentId,jdbcType=VARCHAR}, '%') ) )

SELECT u.id, u.institute_id, u.dept_id, u.referral_code, u.user_code, u.user_name, u.real_name, u.phone, u.email, u.avatar, u.`status`, u.status_time, u.status_memo, u.is_pwd_expired, u.pwd_level, u.pwd_edit_time, u.login_error_count, u.lasted_login_ip, u.lasted_login_time, u.third_id, u.create_time FROM bko_user AS u WHERE u.delete_state = 0
AND u.institute_id IN
#{item}
AND u.institute_id IN ( SELECT id FROM inc_institute WHERE delete_state = 0 AND parent_path Like CONCAT('%', #{instituteParentId,jdbcType=VARCHAR}, '%') )
AND u.institute_id = #{instituteId,jdbcType=VARCHAR}
AND u.id IN
#{item}
EXISTS ( SELECT 1 FROM bko_user_role ur WHERE ur.user_id = u.id AND ur.role_id IN
#{item}
)
